from health_check.backends import BaseHealthCheckBackend
from health_check.exceptions import HealthCheckException
from .models import TenantDatabaseCluster

class MultiTenantDatabaseHealthCheck(BaseHealthCheckBackend):
    critical_service = True

    def check_status(self):
        user = getattr(self.request, 'user', None)
        if not user or not user.is_authenticated or not hasattr(user, 'tenant'):
            raise HealthCheckException("Unauthorized health check access.")

        # Enforce lookup strictly against the authenticated user's assigned tenant
        cluster = TenantDatabaseCluster.objects.filter(tenant=user.tenant).first()
        if not cluster:
            raise HealthCheckException("Cluster configuration not found.")

        # Return high-level operational status without exposing private VPC IP topology
        self.custom_data = {
            "status": "HEALTHY" if cluster.is_available else "DEGRADED",
            "pool_healthy": cluster.active_conn_count < cluster.connection_pool_max
        }
